# ==================== FRAME HEX ====================
JOIN_FRAME_HEX = ""

ONLINE_ROOM_HEX = ""

# ==================== BUILD ACCOUNTS ====================
ACCOUNTS = []

for item in ACCOUNTS_DATA:
    token = item.get("auth_token")
    uid = item.get("uid")
    
    if not token or str(token).startswith("#"):
        continue
        
    ACCOUNTS.append({
        "uid": uid,
        "auth_token": token,
        "join_frame_hex": JOIN_FRAME_HEX,
        "online_room_frame_hex": ONLINE_ROOM_HEX
    })

# ==================== PRINT INFO ====================
print("\n" + "="*70)
print(f"📋 TOTAL {len(ACCOUNTS)} REAL ACCOUNTS LOADED")
print("="*70)
print("-" * 70)
for i, acc in enumerate(ACCOUNTS, 1):
    uid_len = len(str(acc["uid"]))
    print(f"Account {i:2d}: 🟢 ACTIVE")
    print(f"  UID: {acc['uid']} (Length: {uid_len})")
    print(f"  Token: {acc['auth_token'][:50]}...")
    print("-" * 50)
print("="*70)
print(f"✅ Total {len(ACCOUNTS)} accounts ready!")
print("="*70 + "\n")
